import clothes from './clothes.json';
import type { Kind, RigDef } from './rig';

export interface GarmentDef {
  id: string;
  name: string;
  kind: Kind;
  /** swatch colour shown on the card */
  color?: string;
  /** image URL, relative to the app (built-in) or a blob/object URL (user-added) */
  src: string;
  /** natural size of the source image (for the rig; the real size is read when loaded) */
  size?: [number, number];
  rig: RigDef;
  /** added by the user (kept on this device) */
  custom?: boolean;
}

/** Built-in garments. Generated by `scripts/make-clothes.mjs`; add your own images from the app. */
export const BUILT_IN: GarmentDef[] = clothes as GarmentDef[];

export const KIND_LABEL: Record<Kind, string> = {
  top: 'Tops',
  bottom: 'Bottoms',
  dress: 'Dresses',
};

export const KIND_SINGULAR: Record<Kind, string> = {
  top: 'Top',
  bottom: 'Bottom',
  dress: 'Dress',
};

export const KIND_ORDER: Kind[] = ['top', 'bottom', 'dress'];

export interface Outfit {
  top: string | null;
  bottom: string | null;
  dress: string | null;
}

export interface Fit {
  /** scale about the torso centre */
  size: number;
  /** vertical shift in torso lengths */
  dy: number;
}

export const emptyOutfit = (): Outfit => ({ top: null, bottom: null, dress: null });
export const defaultFit = (): Record<Kind, Fit> => ({
  top: { size: 1, dy: 0 },
  bottom: { size: 1, dy: 0 },
  dress: { size: 1, dy: 0 },
});

/** Wearing a dress replaces the top and bottom, and the other way round. */
export function wear(outfit: Outfit, kind: Kind, id: string | null): Outfit {
  const next = { ...outfit, [kind]: id };
  if (id) {
    if (kind === 'dress') {
      next.top = null;
      next.bottom = null;
    } else next.dress = null;
  }
  return next;
}
